sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	current.state = 301;
	if (current.subject_person.preferred_language == 'fq') {
        current.pdf_template = '36e0bbc987013810b7cac956cebb35d6'; // ESDCLAB1069_FQ
    } else {
        current.pdf_template = '83fcd72a2f5b64104cbeb1e72799b67a'; //ESDC-LAB1069
    }

	current.update();

var grSignTask = new GlideRecord("sn_hr_core_task");
		grSignTask.initialize();

		grSignTask.parent = current.sys_id;
		grSignTask.state = 18;
		grSignTask.hr_task_type = "e_sign";
		grSignTask.short_description = "Employee Signature Required (ESDC Form LAB1069) - "+current.number;
		grSignTask.sn_esign_esignature_configuration = "af7e3d0eb7743300a251e556ee11a939";
		grSignTask.assigned_to = current.subject_person;

		grSignTask.insert();

})(current, previous);
